const primaryNavItems=[
  ['stock','◒','Riesgo de stock'],['forecast','↗','Forecast y reposición'],['operations','▤','Operación pedidos/entregas'],['maintenance','⚙','Mantenimiento de activos']
];
const secondaryNavItems=[['summary','⌂','Resumen ejecutivo']];
const state={page:'summary',updated:'Conectando…',mode:'gcp',live:{},master:{stores:[],products:[],categories:[],warehouses:[]},status:{},liveReady:false};
const inventory=[42,36,30,24,18,12,8,5];
const network={customers:42500,stores:32,skus:3200,orders:28000,units:125000,atRisk:68,critical:12,stockValue:'S/ 4.2 M'};
const riskStores=[['STORE-001','Lima Centro',68,12],['STORE-014','San Miguel',54,8],['STORE-032','Surco',41,6],['STORE-077','Arequipa Norte',36,4],['STORE-008','Miraflores',29,3]];
const categories=[['Abarrotes',34,'red'],['Bebidas',26,'amber'],['Lácteos',19,'amber'],['Limpieza',12,''],['Cuidado personal',9,'']];
const fmt=n=>new Intl.NumberFormat('es-PE').format(n);
const badge=(text,type='')=>`<span class="badge ${type}">${text}</span>`;
const actionBadge=action=>{const value=String(action||'REVISAR').toUpperCase();const type=value.includes('REPOS')?'red':value.includes('PRIORIZ')?'amber':'';return badge(value,type)};
const nav=document.querySelector('#navigation');
const routeByPage={summary:'summary',stock:'stock-risk',forecast:'forecast',operations:'operations',maintenance:'maintenance-risks',insights:'insights',market:'market',quality:'quality'};
function statusDot(id){const status=state.status[routeByPage[id]]==='online'?'online':'amber';const label=status==='online'?'Conectado y con datos':'Sin conexión o sin datos';return `<span class="nav-status ${status}" title="${label}">●</span>`}
function navGroup(title,items,collapsed=false){const content=items.map(([id,icon,label])=>`<button class="nav-item ${id===state.page?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span>${label}${statusDot(id)}</button>`).join('');return collapsed?`<details class="nav-group" id="secondary-nav"><summary class="nav-group-label">${title}<span class="nav-group-chevron">⌄</span></summary>${content}</details>`:`<div class="nav-group"><div class="nav-group-label">${title}</div>${content}</div>`}
function renderNav(){const wasOpen=Boolean(nav.querySelector('#secondary-nav')?.open);nav.innerHTML=navGroup('Casos de uso',primaryNavItems)+navGroup('Otras vistas',secondaryNavItems,true);nav.querySelector('#secondary-nav').open=wasOpen||secondaryNavItems.some(([id])=>id===state.page)}
renderNav();
nav.addEventListener('click',e=>{const item=e.target.closest('[data-page]');if(!item)return;state.page=item.dataset.page;render();if(state.liveReady)hydrateLiveView()});
const userButton=document.querySelector('#user-button');const popover=document.querySelector('#user-popover');userButton.addEventListener('click',()=>{const open=popover.classList.toggle('open');userButton.setAttribute('aria-expanded',String(open))});document.addEventListener('click',event=>{if(!event.target.closest('.user-menu')){popover.classList.remove('open');userButton.setAttribute('aria-expanded','false')}});document.querySelector('#refresh-menu').addEventListener('click',()=>{state.updated='Actualizado ahora';popover.classList.remove('open');userButton.setAttribute('aria-expanded','false');connectLive()});
function lineChart(){const max=45,w=700,h=210,points=inventory.map((v,i)=>`${35+i*(w-65)/(inventory.length-1)},${h-20-v/max*(h-35)}`).join(' ');return `<div class="chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="Stock descendente"><line x1="35" y1="${h-20-12/max*(h-35)}" x2="${w-15}" y2="${h-20-12/max*(h-35)}" stroke="#e48882" stroke-dasharray="8 6"/><text x="${w-85}" y="${h-26-12/max*(h-35)}" fill="#c94d4d" font-size="11">Umbral</text><line x1="35" y1="10" x2="35" y2="${h-20}" stroke="#dce5e4"/><line x1="35" y1="${h-20}" x2="${w-15}" y2="${h-20}" stroke="#dce5e4"/><polyline points="${points}" fill="none" stroke="#176d6a" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${inventory.map((v,i)=>{const [x,y]=points.split(' ')[i].split(',');return `<circle cx="${x}" cy="${y}" r="5" fill="${v<=12?'#d95750':'#176d6a'}"/>`}).join('')}</svg><div class="chart-label"><span>Nov 01</span><span>Nov 08</span></div></div>`}
function stockRiskBusinessChart(trend,metrics){if(!trend.length)return '<div class="empty">Sin tendencia de riesgo disponible.</div>';const rows=trend.slice().reverse();const width=820,height=300,left=58,right=24,top=28,bottom=48,plotW=width-left-right,plotH=height-top-bottom;const max=Math.max(1,...rows.map(r=>Math.max(Number(r.risk_rows||0),Number(r.critical_rows||0))));const x=i=>left+(rows.length===1?plotW/2:i*plotW/(rows.length-1));const y=v=>top+plotH-(Number(v||0)/max)*plotH;const riskPoints=rows.map((r,i)=>`${x(i)},${y(r.risk_rows)}`).join(' ');const criticalPoints=rows.map((r,i)=>`${x(i)},${y(r.critical_rows)}`).join(' ');const guides=[0,.25,.5,.75,1].map(p=>{const value=Math.round(max*p);const yy=y(value);return `<line x1="${left}" y1="${yy}" x2="${width-right}" y2="${yy}" stroke="#e8efee"/><text x="${left-10}" y="${yy+4}" text-anchor="end" fill="#78898c" font-size="11">${fmt(value)}</text>`}).join('');const dots=rows.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r.risk_rows)}" r="5" fill="#0e6b68"><title>${r.period_date}: ${fmt(Number(r.risk_rows))} SKUs en riesgo</title></circle><circle cx="${x(i)}" cy="${y(r.critical_rows)}" r="5" fill="#d95750"><title>${r.period_date}: ${fmt(Number(r.critical_rows))} SKUs críticos</title></circle><text x="${x(i)}" y="${height-18}" text-anchor="middle" fill="#78898c" font-size="10">${String(r.period_date).slice(5)}</text>`).join('');const latest=Number(rows.at(-1).risk_rows||0),previous=Number(rows.at(-2)?.risk_rows||latest),delta=previous?Math.round((latest-previous)/previous*100):0;const reading=delta>0?`La exposición aumentó ${Math.abs(delta)}% frente al periodo anterior; conviene priorizar reposición.`:`La exposición se redujo ${Math.abs(delta)}% frente al periodo anterior; la cobertura muestra mejora.`;return `<div class="business-chart"><div class="chart-legend"><span><i class="legend-dot risk"></i>SKUs con riesgo</span><span><i class="legend-dot critical"></i>SKUs críticos</span><strong>${reading}</strong></div><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Evolución de SKUs en riesgo y críticos">${guides}<polyline points="${riskPoints}" fill="none" stroke="#0e6b68" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/><polyline points="${criticalPoints}" fill="none" stroke="#d95750" stroke-width="3" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="7 6"/>${dots}</svg><div class="chart-callout"><strong>Lectura de negocio:</strong> la línea verde muestra la exposición total de productos que pueden romper stock; la roja separa los productos que requieren atención inmediata.</div></div>`}
function operationsBusinessChart(rows){const source=Array.isArray(rows)?rows:[];const data=source.filter(r=>r&&r.period_date&&Number(r.orders||0)>0).slice().reverse();if(!data.length)return '<div class="empty">Sin datos de volumen para el periodo seleccionado.</div>';const max=Math.max(...data.map(r=>Number(r.orders||0)),1);const width=820,height=300,left=58,right=24,top=28,bottom=48,plotW=width-left-right,plotH=height-top-bottom;const x=i=>left+(data.length===1?plotW/2:i*plotW/(data.length-1));const y=v=>top+plotH-(Number(v||0)/max)*plotH;const points=data.map((r,i)=>`${x(i)},${y(r.orders)}`).join(' ');const guides=[0,.25,.5,.75,1].map(p=>{const value=Math.round(max*p);const yy=y(value);return `<line x1="${left}" y1="${yy}" x2="${width-right}" y2="${yy}" stroke="#e8efee"/><text x="${left-10}" y="${yy+4}" text-anchor="end" fill="#78898c" font-size="11">${fmt(value)}</text>`}).join('');const dots=data.map((r,i)=>`<circle cx="${x(i)}" cy="${y(r.orders)}" r="5" fill="#0e6b68"><title>${r.period_date}: ${fmt(Number(r.orders))} pedidos</title></circle><text x="${x(i)}" y="${height-18}" text-anchor="middle" fill="#78898c" font-size="10">${String(r.period_date).slice(5)}</text>`).join('');return `<div class="business-chart"><div class="chart-legend"><span><i class="legend-dot risk"></i>Pedidos procesados</span><strong>Volumen de la operación por periodo</strong></div><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Pedidos procesados por periodo">${guides}<polyline points="${points}" fill="none" stroke="#0e6b68" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${dots}</svg><div class="chart-callout"><strong>Lectura de negocio:</strong> la tendencia permite identificar crecimiento o caída del volumen de pedidos y anticipar capacidad de preparación y entrega.</div></div>`}
const guides={summary:'Empieza aquí para entender el estado general de la operación.',stock:'Lee la cobertura, identifica los productos con riesgo y revisa las tiendas afectadas.',forecast:'Consulta la demanda esperada y las cantidades que conviene reponer.',operations:'Revisa pedidos, entregas y niveles de servicio de la operación.',maintenance:'Identifica activos que requieren atención antes de afectar la operación.',insights:'Sigue señales recientes que requieren atención del equipo.',market:'Observa cambios de precios, eventos y señales de demanda del mercado.',quality:'Confirma que la información esté disponible, actualizada y trazable.'};
const businessStories={
  stock:['Evitar quiebres de stock','Detecta productos y tiendas con disponibilidad comprometida.','Abre los SKU críticos y prioriza su reposición.'],
  forecast:['Reponer con anticipación','Compara demanda prevista y unidades recomendadas por fecha.','Revisa producto, centro y prioridad antes de aprobar un plan.'],
  operations:['Cumplir la promesa de entrega','Observa cómo evoluciona el volumen de pedidos.','Revisa el periodo y dimensiona preparación y distribución.'],
  maintenance:['Proteger la continuidad operativa','Ubica activos con señales críticas o preventivas.','Prioriza la revisión del sensor y del centro afectado.']
};
function businessIntro(id){const story=businessStories[id];return story?`<section class="business-story" aria-label="Objetivo del caso de uso"><div><span class="eyebrow">Objetivo</span><h2>${story[0]}</h2></div><p>${story[1]}</p><p><strong>Siguiente acción:</strong> ${story[2]}</p></section>`:''}
function page(title,body){let view=body.replaceAll('escenario sintético','operación consolidada').replaceAll('Batch + streaming · operación consolidada','Información de la operación').replaceAll('Batch + tiempo real','Operación integrada').replaceAll('Drill-down disponible','Ver detalle').replaceAll('Ver 3,200 SKUs por tienda, categoría y cobertura','Abrir detalle por tienda, categoría y producto').replaceAll('Pub/Sub → Dataflow → Gold','Eventos recientes');if(state.mode==='local')view=view.replaceAll('42.5 K','467 K').replaceAll('86 / 3.2 K','43 / 9.2 K').replaceAll('—','143.2 K').replaceAll('125 K','620 K');if(state.mode==='gcp'&&!state.liveReady){view=view.replaceAll('42.5 K','—').replaceAll('86 / 3.2 K','—').replaceAll('—','—').replaceAll('125 K','—').replaceAll('3.2 K','—')}document.querySelector('#page-title').textContent=title;document.querySelector('#page-content').innerHTML=`<div class="screen-guide"><button class="info-trigger" type="button" aria-label="Información de la vista">i</button><span>${guides[state.page]}</span></div>${businessIntro(state.page)}${view}<div class="detail-bar"><span>Consulta el detalle de esta vista</span><button class="detail-button js-detail" data-detail="${state.page}">Ver información detallada</button></div>`;document.querySelectorAll('.nav-item').forEach(x=>x.classList.toggle('active',x.dataset.page===state.page));renderNav()}

function blankNumericDefaults(){const root=document.querySelector('#page-content');if(!root)return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];let node;while(node=walker.nextNode())nodes.push(node);nodes.forEach(textNode=>{textNode.nodeValue=textNode.nodeValue.replace(/\b\d[\d,.]*(?:\s*[KkMm])?%?/g,'—')})}
const renderPageWithGcpGuard=page;page=function(title,body){renderPageWithGcpGuard(title,body);if(state.mode==='gcp'&&!state.liveReady){blankNumericDefaults()}}
function detailRows(kind){const rows=state.master[kind]||[];return rows.slice(0,25).map(row=>`<tr>${Object.entries(row).slice(0,6).map(([key,value])=>`<td><strong>${key.endsWith('_id')?value:''}</strong>${key.endsWith('_id')?'':(value??'')}</td>`).join('')}</tr>`).join('')}
function openDetail(pageId){const mapping={summary:['Resumen consolidado','stores','Tiendas afectadas y cobertura de la operación'],stock:['Riesgo de inventario','products','Productos, categorías y estado de cobertura'],forecast:['Planes de reposición','products','Productos vinculados a los planes de reposición'],operations:['Operación de pedidos','stores','Tiendas y centros que reciben la operación'],maintenance:['Activos y alertas','warehouses','Centros de distribución relacionados'],insights:['Señales recientes','products','Productos asociados a señales de mercado y demanda'],market:['Contexto de mercado','products','Productos observados en el mercado'],quality:['Catálogo y trazabilidad','categories','Categorías maestras disponibles']};const [title,kind,subtitle]=mapping[pageId]||mapping.summary;const rows=state.master[kind]||[];const columns=rows.length?Object.keys(rows[0]).slice(0,6):[];const modal=document.createElement('div');modal.className='detail-modal';modal.innerHTML=`<div class="detail-panel" role="dialog" aria-modal="true"><div class="detail-head"><div><span class="eyebrow">Detalle conectado</span><h2>${title}</h2><p>${subtitle}</p></div><button class="detail-close" aria-label="Cerrar">×</button></div><div class="detail-meta"><span>${rows.length} registros disponibles</span><span>Catálogo maestro</span></div><div class="table-wrap"><table class="data-table"><thead><tr>${columns.map(column=>`<th>${column.replaceAll('_',' ')}</th>`).join('')}</tr></thead><tbody>${detailRows(kind)}</tbody></table></div></div>`;document.body.appendChild(modal);modal.querySelector('.detail-close').onclick=()=>modal.remove();modal.onclick=e=>{if(e.target===modal)modal.remove()}}
function openCriticalModal(rows,title='SKUs críticos',context={}){
  const pageSize=25;let pageNumber=0;
  const riskCount=Number(context.riskCount??rows.length),criticalCount=Number(context.criticalCount??rows.length);
  const modal=document.createElement('div');modal.className='detail-modal';
  modal.innerHTML=`<div class="detail-panel" role="dialog" aria-modal="true"><div class="detail-head"><div><span class="eyebrow">Detalle de riesgo</span><h2>${title}</h2><p>Productos con riesgo alto o reposición prioritaria identificados para revisión.</p></div><button class="detail-close" aria-label="Cerrar">×</button></div><div class="risk-modal-summary"><div><span>SKUs con riesgo</span><strong>${fmt(riskCount)}</strong></div><div class="critical"><span>SKUs críticos</span><strong>${fmt(criticalCount)}</strong></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>SKU</th><th>Producto</th><th>Categoría</th><th>Tienda</th><th>Zona</th><th>Disponible</th><th>Riesgo</th><th>Acción</th></tr></thead><tbody></tbody></table></div><div class="modal-pagination"><button class="page-prev" type="button">Anterior</button><span class="page-label"></span><button class="page-next" type="button">Siguiente</button></div></div>`;
  document.body.appendChild(modal);
  const renderRows=()=>{const start=pageNumber*pageSize;const visible=rows.slice(start,start+pageSize);modal.querySelector('tbody').innerHTML=visible.map(r=>`<tr><td><strong>${r.sku_id||'—'}</strong></td><td>${r.product_name||'—'}</td><td>${r.category_name||'—'}</td><td>${r.store_id||'—'}</td><td>${r.zone_name||'—'}</td><td>${r.available_qty??'—'}</td><td><strong class="risk-percent">${Math.round(Number(r.risk_score||0)*100)}%</strong></td><td>${actionBadge(r.recommended_action)}</td></tr>`).join('')||'<tr><td colspan="8">No hay SKUs críticos para esta selección.</td></tr>';const pages=Math.max(1,Math.ceil(rows.length/pageSize));modal.querySelector('.page-label').textContent=`Página ${pageNumber+1} de ${pages}`;modal.querySelector('.page-prev').disabled=pageNumber===0;modal.querySelector('.page-next').disabled=pageNumber>=pages-1};
  renderRows();modal.querySelector('.page-prev').onclick=()=>{if(pageNumber>0){pageNumber--;renderRows()}};modal.querySelector('.page-next').onclick=()=>{if((pageNumber+1)*pageSize<rows.length){pageNumber++;renderRows()}};modal.querySelector('.detail-close').onclick=()=>modal.remove();modal.onclick=e=>{if(e.target===modal)modal.remove()};
}
document.addEventListener('click',event=>{const trigger=event.target.closest('.js-detail');if(trigger)openDetail(trigger.dataset.detail)});
function summary(){return `<div class="hero-note"><span class="health">● Estado de la operación</span><strong>${fmt(network.customers)} clientes atendidos este mes en ${network.stores} tiendas y ${fmt(network.skus)} SKUs.</strong><span class="subtle">${state.updated}</span></div><div class="section-heading"><h2>Vista ejecutiva de la red</h2><span class="subtle">Batch + streaming · escenario sintético</span></div><div class="grid kpi-grid"><div class="card metric"><span class="label">Clientes activos / mes</span><span class="value">42.5 K</span><span class="delta positive">Clientes atendidos</span></div><div class="card metric"><span class="label">Tiendas / SKUs monitoreados</span><span class="value">—</span><span class="delta positive">Cobertura nacional</span></div><div class="card metric"><span class="label">Pedidos procesados</span><span class="value">—</span><span class="delta positive">Pedidos del periodo</span></div><div class="card metric"><span class="label">Unidades movidas</span><span class="value">125 K</span><span class="delta positive">Batch + tiempo real</span></div></div><div class="section-heading"><h2>Situación global de inventario</h2><span class="subtle">${network.atRisk} SKUs en riesgo · ${network.critical} críticos</span></div><div class="grid two-col"><div class="card"><div class="stat-strip"><div class="stat-box"><span class="subtle">Valor de inventario</span><strong>—</strong></div><div class="stat-box"><span class="subtle">SKUs en riesgo</span><strong class="negative">—</strong></div><div class="stat-box"><span class="subtle">Tiendas afectadas</span><strong class="warning">—</strong></div></div><div class="alert-list" style="margin-top:16px"><div class="alert"><div class="alert-main"><span class="alert-icon">!</span><div><strong>Concentración crítica</strong><div class="subtle">Consulta los productos prioritarios en riesgo de stock</div></div></div>${badge('HIGH','red')}</div><div class="alert"><div class="alert-main"><span class="alert-icon amber">!</span><div><strong>Demanda por encima del forecast</strong><div class="subtle">Revisa los planes de reposición para anticipar necesidades</div></div></div>${badge('Atención','amber')}</div></div></div><div class="card"><h2>Riesgo por categoría</h2><div class="alert-list">${categories.map(([name,value,type])=>`<div><div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px"><span>${name}</span><strong>${value}%</strong></div><div style="height:7px;background:#edf2f1;border-radius:9px"><div style="height:100%;width:${value*2.1}%;max-width:100%;background:${type==='red'?'#d95750':type==='amber'?'#d99a38':'#5ba98e'};border-radius:9px"></div></div></div>`).join('')}</div></div></div><div class="section-heading"><h2>Alertas priorizadas por red</h2><span class="subtle">Selecciona una alerta para bajar al SKU y tienda</span></div><div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Tienda</th><th>Zona</th><th>SKUs en riesgo</th><th>Críticos</th><th>Estado</th></tr></thead><tbody>${riskStores.map(([store,zone,risk,critical])=>`<tr><td><strong>${store}</strong></td><td>${zone}</td><td>${risk}</td><td>${critical}</td><td>${badge(critical>8?'Atención':'Monitorear',critical>8?'red':'amber')}</td></tr>`).join('')}</tbody></table></div></div>`}
function stock(){return `<div class="hero-note"><span class="health">● Cómo leer esta vista</span><strong>Revisa las señales de riesgo para priorizar productos y tiendas. “Crítico” indica riesgo alto o necesidad de reposición inmediata.</strong><button class="detail-button js-critical-all" type="button">Ver críticos</button></div><div class="grid kpi-grid"><div class="card metric"><span class="label">SKUs monitoreados</span><span class="value">—</span><span class="delta positive">Productos evaluados en la red</span></div><div class="card metric"><span class="label">SKUs con riesgo de quiebre</span><span class="value negative">—</span><span class="delta negative">Según el nivel de riesgo</span></div><div class="card metric"><span class="label">Disponibilidad promedio</span><span class="value">—</span><span class="delta warning">Unidades disponibles por registro</span></div><div class="card metric"><span class="label">SKUs críticos</span><span class="value">—</span><span class="delta negative">Riesgo alto o reposición prioritaria</span></div></div><div class="filter-row" style="margin-top:18px"><select id="stock-store-filter"><option value="">Toda la red · 32 tiendas</option><option value="Lima">Lima</option><option value="Provincias">Provincias</option></select><select id="stock-category-filter"><option value="">Todas las categorías</option><option value="Abarrotes">Abarrotes</option><option value="Bebidas">Bebidas</option></select><select id="stock-risk-filter"><option value="">Todos los niveles de riesgo</option><option value="critical">Solo SKUs críticos</option></select></div><div class="grid two-col"><div class="card"><div class="section-heading" style="margin-top:0"><div><h2>Tendencia de SKUs con riesgo de quiebre</h2><span class="subtle">Total de productos con inventario insuficiente por periodo</span></div>${badge('Red completa','amber')}</div><div class="chart" id="stock-risk-chart">${lineChart()}</div><p class="subtle">Cada punto representa cuántos SKUs estuvieron en riesgo en toda la red durante ese periodo. Una subida significa mayor exposición y requiere revisar reposición.</p></div><div class="card"><h2>Concentración del riesgo por tienda</h2><p class="subtle">Muestra dónde se acumulan los productos con riesgo. Haz clic en el círculo para ver todos los SKUs críticos de esa tienda.</p><div class="table-wrap"><table class="data-table"><thead><tr><th>Tienda</th><th>Zona</th><th>SKUs con riesgo</th><th>SKUs críticos</th></tr></thead><tbody>${riskStores.map(([store,zone,risk,critical])=>`<tr class="risk-store-row" data-store="${store}" data-zone="${zone}"><td><strong>${store}</strong></td><td>${zone}</td><td>${risk}</td><td><button class="critical-circle js-critical-store ${critical>0?'has-critical':''}" data-store="${store}" type="button" aria-label="Ver ${critical} SKUs críticos de ${store}">${critical}</button></td></tr>`).join('')}</tbody></table></div><div class="alert" style="margin-top:15px"><div><strong>Qué hacer ahora</strong><div class="subtle">Selecciona el círculo de una tienda o “Ver críticos” para identificar producto, categoría, cobertura y acción recomendada.</div></div><span class="subtle">→</span></div></div></div>`}
function forecast(){return `<div class="grid kpi-grid"><div class="card metric"><span class="label">SKUs con forecast</span><span class="value">—</span><span class="delta positive">Fechas incluidas en el plan</span></div><div class="card metric"><span class="label">Planes generados</span><span class="value">—</span><span class="delta warning">Planes con fecha y prioridad</span></div><div class="card metric"><span class="label">Demanda proyectada</span><span class="value">—</span><span class="delta positive">Total de fechas del plan</span></div><div class="card metric"><span class="label">Unidades recomendadas</span><span class="value">—</span><span class="delta positive">Unidades recomendadas</span></div></div><div class="grid two-col" style="margin-top:16px"><div class="card"><div class="section-heading" style="margin-top:0"><h2>Proyección agregada de demanda</h2>${badge('Plan de reposición')}</div><div class="chart" id="forecast-chart"><div class="empty">Cargando proyección de demanda…</div></div><p class="subtle">Vista consolidada de demanda para toda la red; el detalle por SKU y centro se abre desde el plan.</p></div><div class="card"><h2>Planes prioritarios · producto y centro</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Producto / centro</th><th>Forecast</th><th>Reponer</th><th>Prioridad</th></tr></thead><tbody><tr><td colspan="4">Cargando planes de reposición…</td></tr></tbody></table></div></div></div>`}
function operations(){return `<div class="hero-note"><span class="health">● Cómo leer esta vista</span><strong>Supervisa el volumen de pedidos, el cumplimiento de entrega y las órdenes que requieren intervención.</strong></div><div class="grid kpi-grid"><div class="card metric"><span class="label">Pedidos procesados</span><span class="value">—</span><span class="delta positive">Volumen total de la operación</span></div><div class="card metric"><span class="label">Cumplimiento de entrega</span><span class="value positive">—</span><span class="delta positive">Entregas realizadas dentro del compromiso</span></div><div class="card metric"><span class="label">Unidades movidas</span><span class="value">—</span><span class="delta warning">Volumen físico gestionado</span></div><div class="card metric"><span class="label">Pedidos que requieren atención</span><span class="value negative">—</span><span class="delta negative">Órdenes en riesgo o con incidencia</span></div></div><div class="card" style="margin-top:16px"><div class="section-heading" style="margin-top:0"><div><h2>Volumen y cumplimiento por periodo</h2><span class="subtle">Evolución de pedidos, entregas cumplidas y órdenes que requieren atención</span></div></div><div id="operations-chart" class="chart"><div class="empty">Cargando tendencia operativa…</div></div></div><div class="card" style="margin-top:16px"><div class="section-heading" style="margin-top:0"><div><h2>Pedidos y entregas · detalle operativo</h2><span class="subtle">Consulta el estado y el volumen de cada registro</span></div><select id="operations-status-filter"><option value="">Todos los estados</option><option value="DELIVERED">Entregados</option><option value="IN_TRANSIT">En tránsito</option><option value="AT_RISK">En riesgo</option></select></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Pedido / evento</th><th>Tienda</th><th>Unidades</th><th>Fecha</th><th>Estado</th></tr></thead><tbody><tr><td colspan="5">Cargando registros operativos…</td></tr></tbody></table></div></div>`}
function insights(){const feed=[['10:24:31','Venta SKU-001 (+3 u.) · STORE-001','green'],['10:24:18','Stock bajo (138 u.) · SKU-002','amber'],['10:23:57','Pico de demanda (+28%) · Cat. Bebidas','green'],['10:23:41','Retraso de entrega (15 min) · PO-7846','red'],['10:23:09','Reposición sugerida · SKU-001','green']];return `<div class="hero-note"><span class="health">● Streaming activo</span><strong>32 eventos procesados en los últimos 15 minutos</strong></div><div class="card" style="margin-top:16px"><div class="section-heading" style="margin-top:0"><h2>Feed de insights</h2><span class="subtle">Pub/Sub → Dataflow → Gold</span></div><div class="feed">${feed.map(([time,title,type])=>`<div class="feed-item"><span class="feed-time">${time}</span><span class="feed-dot ${type==='red'?'red':type==='amber'?'amber':''}"></span><div><div class="feed-title">${title}</div><div class="feed-desc">Insight generado y disponible para consumo</div></div></div>`).join('')}</div></div>`}
function market(){return `<div class="grid two-col"><div class="card"><h2>Precio competidor · SKU-001</h2><div class="metric"><span class="value">$ 9.90</span><span class="delta negative">▲ 4% vs. ayer</span></div><div class="mini-bars">${[50,55,48,65,70,62,82].map((h,i)=>`<span class="bar ${i===6?'hot':''}" style="height:${h}%"></span>`).join('')}</div><div class="bar-labels"><span>Lun</span><span>Mar</span><span>Mié</span><span>Jue</span><span>Vie</span><span>Sáb</span><span>Dom</span></div></div><div class="card"><h2>Eventos de mercado</h2><div class="alert-list"><div class="alert"><div><strong>Promoción competidor</strong><div class="subtle">Impacto esperado alto</div></div>${badge('Hoy','red')}</div><div class="alert"><div><strong>Feria local en zona</strong><div class="subtle">STORE-001 · +0.7 impacto</div></div>${badge('Activo','amber')}</div><div class="alert"><div><strong>Sentimiento en redes</strong><div class="subtle">Tendencia favorable</div></div>${badge('+0.62')}</div></div></div></div>`}
function quality(){return `<div class="grid kpi-grid"><div class="card metric"><span class="label">Calidad de datos</span><span class="value positive">98.7%</span><span class="delta positive">Dentro de objetivo</span></div><div class="card metric"><span class="label">Datos frescos</span><span class="value positive">Sí</span><span class="delta">Última carga hace 2 min</span></div><div class="card metric"><span class="label">API salud</span><span class="value positive">OK</span><span class="delta">99.9% disponibilidad</span></div><div class="card metric"><span class="label">Linaje</span><span class="value">Completo</span><span class="delta positive">8 fuentes verificadas</span></div></div><div class="grid two-col" style="margin-top:16px"><div class="card"><h2>Frescura del pipeline</h2><div class="alert-list"><div class="alert"><span>Fuentes → Bronze</span>${badge('5 min')}</div><div class="alert"><span>Bronze → Silver</span>${badge('8 min')}</div><div class="alert"><span>Silver → Gold</span>${badge('10 min')}</div><div class="alert"><span>Gold → API / Reporting</span>${badge('2 min')}</div></div></div><div class="card"><h2>Linaje del producto</h2><div style="display:grid;place-items:center;gap:10px;padding:12px"><div class="stat-box" style="width:90%;text-align:center">Fuentes (POS · ERP · e-commerce)</div><span>↓</span><div class="stat-box" style="width:80%;text-align:center">Bronze / Silver</div><span>↓</span><div class="stat-box" style="width:70%;text-align:center">Gold</div><span>↓</span><div class="stat-box" style="width:60%;text-align:center;background:var(--mint)">API / Reporting</div></div></div></div>`}
function maintenance(){return `<div class="hero-note"><span class="health">● Cómo leer esta vista</span><strong>Supervisa alertas de activos, severidad y señales que podrían afectar la continuidad de las tiendas.</strong></div><div class="grid kpi-grid"><div class="card metric"><span class="label">Activos con señales</span><span class="value">—</span><span class="delta positive">Activos presentes en alertas</span></div><div class="card metric"><span class="label">Activos con alertas críticas</span><span class="value negative">—</span><span class="delta negative">Requieren intervención prioritaria</span></div><div class="card metric"><span class="label">Activos con alertas preventivas</span><span class="value warning">—</span><span class="delta warning">Señales para seguimiento</span></div><div class="card metric"><span class="label">Activos con señales registradas</span><span class="value positive">—</span><span class="delta positive">Eventos disponibles para análisis</span></div></div><div class="grid two-col" style="margin-top:16px"><div class="card"><h2>Alertas de activos</h2><div class="table-wrap"><table class="data-table"><thead><tr><th>Activo</th><th>Ubicación</th><th>Señal observada</th><th>Severidad</th></tr></thead><tbody><tr><td colspan="4">Cargando alertas de activos…</td></tr></tbody></table></div></div><div class="card"><h2>Tendencia de alertas</h2><div class="metric"><span class="value">—</span><span class="delta">Indicador de señal</span></div><div class="chart" id="maintenance-chart"><div class="empty">Cargando tendencia de mantenimiento…</div></div></div></div>`}
function render(){const pages={summary:['Resumen ejecutivo',summary],stock:['Riesgo de stock',stock],forecast:['Forecast y reposición',forecast],operations:['Operación pedidos/entregas',operations],maintenance:['Mantenimiento de activos',maintenance],insights:['Insights tiempo real',insights],market:['Mercado y contexto',market],quality:['Calidad y trazabilidad',quality]};const [title,fn]=pages[state.page];page(title,fn())}
function hydrateLiveView(){
  const kpis=state.live.kpis?.data||[], kpi=kpis[0];
  const stockRisk=state.live['stock-risk']?.data||{}, risks=stockRisk.critical_skus||[], forecastData=state.live.forecast?.data||{}, plans=state.live['inventory-plans']?.data||[], maintenanceRows=state.live['maintenance-risks']?.data||[], insightRows=[];
  const operationsRows=state.live.operations?.data||[], operationsAnalytics=state.live['operations-analytics']?.data||{}, maintenanceAnalytics=state.live['maintenance-analytics']?.data||{}, marketRows=state.live.market?.data||[], qualityData=state.live.quality?.data||{}, summaryData=state.live.summary?.data||{};
  const values=[...document.querySelectorAll('.metric .value')];
  if(state.page==='summary'){
    const summaryValues=values;
    if(summaryValues[0])summaryValues[0].textContent=summaryData.active_customers==null?'—':fmt(Number(summaryData.active_customers));
    if(summaryValues[1])summaryValues[1].textContent=`${fmt(Number(summaryData.total_stores||0))} / ${fmt(Number(summaryData.total_products||0))}`;
    if(summaryValues[2])summaryValues[2].textContent=fmt(Number(summaryData.orders||0));
    if(summaryValues[3])summaryValues[3].textContent=fmt(Number(summaryData.units||0));
    const hero=document.querySelector('.hero-note strong');if(hero)hero.textContent=`${summaryData.active_customers==null?'—':fmt(Number(summaryData.active_customers))} clientes atendidos este mes en ${fmt(Number(summaryData.total_stores||0))} tiendas y ${fmt(Number(summaryData.total_products||0))} SKUs.`;
    const inventoryHeading=document.querySelectorAll('.section-heading')[1]?.querySelector('.subtle');if(inventoryHeading)inventoryHeading.textContent=`${fmt(Number(summaryData.at_risk||0))} SKUs en riesgo · ${fmt(Number(summaryData.critical||0))} críticos`;
    const categoryCard=document.querySelectorAll('.grid.two-col .card')[1];const categoryList=categoryCard?.querySelector('.alert-list');if(categoryList)categoryList.innerHTML=(summaryData.categories||[]).map(c=>`<div><div style="display:flex;justify-content:space-between;font-size:12px;margin-bottom:5px"><span>${c.name||'—'}</span><strong>${fmt(Number(c.risk_count||0))}</strong></div><div style="height:7px;background:#edf2f1;border-radius:9px"><div style="height:100%;width:${Math.min(100,Number(c.risk_count||0)/Math.max(1,Number(summaryData.at_risk||1))*100)}%;background:#d99a38;border-radius:9px"></div></div></div>`).join('')||'<div class="empty">Sin categorías de riesgo en Gold.</div>';
    const summaryRows=document.querySelector('.data-table tbody');
    if(summaryRows&&risks.length){const storeById=new Map(state.master.stores.map(s=>[s.store_id,s]));const criticalByStore=new Map();risks.forEach(r=>{if(Number(r.risk_score||0)>=.5||String(r.recommended_action||'').startsWith('REPOSICIONAR'))criticalByStore.set(r.store_id,(criticalByStore.get(r.store_id)||0)+1)});summaryRows.innerHTML=risks.slice(0,10).map(r=>{const store=storeById.get(r.store_id)||{};return `<tr><td><strong>${r.store_id||'—'}</strong></td><td>${store.zone_name||store.city||'—'}</td><td>${r.available_qty??'—'}</td><td>${criticalByStore.get(r.store_id)||0}</td><td>${badge(r.recommended_action||'MONITOREAR',r.recommended_action?.includes('REPOSICIONAR')?'red':'amber')}</td></tr>`}).join('')}
  }
  if(state.page==='operations'&&kpi&&values[0]) values[0].textContent=fmt(Number(kpi.orders||0));
  if(state.page==='operations'){const rows=Array.isArray(operationsRows)?operationsRows:[];const opm=operationsAnalytics.metrics||{};const sla=Number(opm.sla_rate||0);const attention=Number(opm.attention||0);if(values[1])values[1].textContent=sla?`${fmt(Math.round(sla*100))}%`:'—';if(values[2])values[2].textContent=fmt(Number(opm.units||kpi?.units||0));if(values[3])values[3].textContent=opm.attention==null?'—':fmt(attention);const chart=document.querySelector('#operations-chart');if(chart){try{chart.innerHTML=operationsBarChart(operationsAnalytics.trend||kpiRows)}catch(error){console.error('No se pudo pintar tendencia operativa',error);chart.innerHTML='<div class="empty">No hay una tendencia disponible para el periodo seleccionado.</div>'}}const renderOperations=()=>{const selected=document.querySelector('#operations-status-filter')?.value||'';const filtered=rows.filter(r=>!selected||String(r.status||'').toUpperCase()===selected);const tbody=document.querySelector('.data-table tbody');if(tbody)tbody.innerHTML=filtered.slice(0,25).map(operationRowMarkup).join('')||'<tr><td colspan="5">No hay registros para este filtro.</td></tr>'};try{renderOperations()}catch(error){console.error('No se pudo pintar detalle operativo',error);const tbody=document.querySelector('.data-table tbody');if(tbody)tbody.innerHTML='<tr><td colspan="5">No hay registros operativos disponibles.</td></tr>'}document.querySelector('#operations-status-filter')?.addEventListener('change',renderOperations)}
  if(state.page==='stock'){
    const m=stockRisk.metrics||{},concentration=stockRisk.concentration||[],criticalRows=stockRisk.critical_skus||[],trend=stockRisk.trend||[];
    if(values[0])values[0].textContent=fmt(Number(m.monitored_skus||0));if(values[1])values[1].textContent=fmt(Number(m.risk_rows||0));if(values[2])values[2].textContent=fmt(Number(m.avg_available_qty||0));if(values[3])values[3].textContent=fmt(Number(m.critical_rows||0));
    const exposure=Number(m.monitored_skus)?Number(m.risk_rows||0)/Number(m.monitored_skus)*100:0,previous=Number(trend[1]?.risk_rows||0),current=Number(trend[0]?.risk_rows||0),improvement=previous?Math.max(0,(previous-current)/previous*100):0;
    const kpiGrid=document.querySelector('.kpi-grid');if(kpiGrid&&!document.querySelector('.stock-snapshot'))kpiGrid.insertAdjacentHTML('afterend',`<section class="stock-snapshot" aria-label="Resumen de exposición"><div class="snapshot-ring" style="--value:${Math.min(100,exposure)}"><strong>${exposure.toFixed(1)}%</strong><span>del catálogo en riesgo</span></div><div class="snapshot-trend"><span>Mejora diaria</span><strong>↓ ${improvement.toFixed(1)}%</strong><small>${fmt(previous)} a ${fmt(current)} SKUs con riesgo</small></div><p><strong>Lectura ejecutiva:</strong> la plataforma concentra la atención en una fracción acotada del catálogo y muestra si la exposición mejora frente al día anterior.</p></section>`);
    const tbody=document.querySelector('.data-table tbody');if(tbody)tbody.innerHTML=concentration.slice(0,10).map(r=>`<tr class="risk-store-row" data-store="${r.store_id||''}" data-risk="${r.risk_rows??0}" data-critical="${r.critical_rows??0}"><td><strong>${r.store_id||'—'}</strong></td><td>${r.zone_name||'—'}</td><td>${r.risk_rows??'—'}</td><td><button class="critical-circle js-critical-store ${Number(r.critical_rows)>0?'has-critical':''}" data-store="${r.store_id||''}" data-risk="${r.risk_rows??0}" data-critical="${r.critical_rows??0}" type="button" aria-label="Ver ${r.critical_rows??0} SKUs críticos de ${r.store_id||''}">${r.critical_rows??0}</button></td></tr>`).join('')||'<tr><td colspan="4">Sin concentración de riesgo disponible.</td></tr>';
    const chart=document.querySelector('#stock-risk-chart');if(chart)chart.innerHTML=stockRiskBusinessChart(trend,m);
    const openStore=(element)=>{const store=element.dataset.store,storeRows=criticalRows.filter(r=>r.store_id===store);openCriticalModal(storeRows,`Riesgo de stock · ${store}`,{riskCount:Number(element.dataset.risk||storeRows.length),criticalCount:Number(element.dataset.critical||storeRows.length)})};
    document.querySelectorAll('.js-critical-store').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();openStore(button)}));document.querySelector('.js-critical-all')?.addEventListener('click',()=>openCriticalModal(criticalRows,'SKUs críticos · red completa',{riskCount:Number(m.risk_rows||0),criticalCount:Number(m.critical_rows||0)}));document.querySelectorAll('.risk-store-row').forEach(row=>row.addEventListener('click',event=>{if(!event.target.closest('.js-critical-store'))openStore(row)}));document.querySelector('#stock-risk-filter')?.addEventListener('change',event=>{document.querySelectorAll('.risk-store-row').forEach(row=>row.style.display=event.target.value==='critical'&&Number(row.dataset.critical||0)===0?'none':'')});
  }
  if(state.page==='forecast'){const m=forecastData.metrics||{};if(values[0])values[0].textContent=fmt(Number(m.forecast_skus||0));if(values[1])values[1].textContent=fmt(Number(m.plan_rows||0));if(values[2])values[2].textContent=fmt(Number(m.forecast_qty||0));if(values[3])values[3].textContent=fmt(Number(m.recommended_qty||0));const tbody=document.querySelector('.data-table tbody');if(tbody)tbody.innerHTML=(forecastData.plans||[]).slice(0,10).map(p=>`<tr><td><strong>${p.product_name||p.sku_id}</strong><div class="subtle">${p.sku_id} · ${p.category_name}</div><div class="subtle">${p.warehouse_name||p.warehouse_id} · ${p.plan_date}</div></td><td>${fmt(Number(p.forecast_qty||0))} u.</td><td>${fmt(Number(p.recommended_qty||0))} u.</td><td>${badge(p.priority,p.priority==='HIGH'?'red':'amber')}</td></tr>`).join('')||'<tr><td colspan="4">No hay planes prioritarios con producto identificado.</td></tr>';const chart=document.querySelector('#forecast-chart');const trend=forecastData.trend||[];if(chart){const max=Math.max(1,...trend.map(t=>Number(t.forecast_qty||0)));chart.innerHTML=trend.length?`<div class="forecast-bars" role="img" aria-label="Demanda prevista y reposición recomendada por fecha">${trend.map(t=>`<div class="forecast-row"><span class="forecast-date">${String(t.plan_date).slice(5)}</span><div class="forecast-track"><i style="width:${Math.min(100,Number(t.forecast_qty||0)/max*100)}%"></i></div><strong>${fmt(Number(t.forecast_qty||0))} u.</strong><small>Reponer ${fmt(Number(t.recommended_qty||0))} u.</small></div>`).join('')}</div>`:'<div class="empty">Sin proyección disponible.</div>'}}
  if(state.page==='maintenance'){const mm=maintenanceAnalytics.metrics||{};if(values[0])values[0].textContent=fmt(Number(mm.monitored_assets||0));if(values[1])values[1].textContent=fmt(Number(mm.high_alerts||0));if(values[2])values[2].textContent=fmt(Number(mm.medium_alerts||0));if(values[3])values[3].textContent=fmt(Number(mm.total_alerts||0));const warehouseById=new Map(state.master.warehouses.map(w=>[w.warehouse_id,w]));const tbody=document.querySelector('.data-table tbody');if(tbody)tbody.innerHTML=maintenanceRows.slice(0,25).map(m=>{const warehouse=warehouseById.get(m.warehouse_id)||{};const location=warehouse.warehouse_name||warehouse.city||m.warehouse_id||'Ubicación registrada';const severity=String(m.severity||'NORMAL').toUpperCase();const severityLabel=severity==='HIGH'?'Crítica':severity==='MEDIUM'?'Preventiva':'Seguimiento';const assetType=String(m.anomaly_type||'Activo operativo').replaceAll('_',' ').toLowerCase();return `<tr><td><strong>${m.asset_id||'Activo registrado'}</strong><div class="subtle">${assetType}</div></td><td>${location}<div class="subtle">${warehouse.city||'Centro operativo'}</div></td><td>${m.sensor_id||'Sensor operativo'}<div class="subtle">${m.metric_value??'—'} lectura</div></td><td>${badge(severityLabel,severity==='HIGH'?'red':severity==='MEDIUM'?'amber':'')}</td></tr>`}).join('')||'<tr><td colspan="4">No hay alertas de mantenimiento disponibles.</td></tr>';const sensorValue=document.querySelector('.two-col .metric .value');if(sensorValue)sensorValue.textContent=mm.avg_metric_value!=null?`${mm.avg_metric_value}`:'—';const chart=document.querySelector('#maintenance-chart');if(chart)chart.innerHTML=maintenanceSeverityChart(maintenanceAnalytics.trend||[])}
  if(state.page==='insights'){const feed=document.querySelector('.feed');if(feed&&insightRows.length)feed.innerHTML=insightRows.slice(0,15).map(i=>`<div class="feed-item"><span class="feed-time">${String(i.created_at||'').slice(11,19)}</span><span class="feed-dot"></span><div><div class="feed-title">${i.insight_type||'Insight'} · ${i.event_id||'—'}</div><div class="feed-desc">Disponible en Gold</div></div></div>`).join('')}
  if(state.page==='market'){const marketValues=[...document.querySelectorAll('.metric .value')];if(marketValues[0])marketValues[0].textContent=marketRows.length?fmt(Number(marketRows[0].measure_value||0)):'—';const list=document.querySelector('.alert-list');if(list)list.innerHTML=marketRows.slice(0,10).map(r=>`<div class="alert"><div><strong>${r.entity_type||'Evento'}</strong><div class="subtle">${r.entity_id||'—'} · ${r.store_id||'—'}</div></div>${badge(r.status||'Disponible','amber')}</div>`).join('')||'<div class="subtle">Sin eventos de mercado en Gold.</div>'}
  if(state.page==='quality'){const qualityValues=[...document.querySelectorAll('.metric .value')];if(qualityValues[0])qualityValues[0].textContent=qualityData.records?fmt(Number(qualityData.populated||0)):'—';if(qualityValues[1])qualityValues[1].textContent=qualityData.last_observed?'Sí':'—';if(qualityValues[2])qualityValues[2].textContent='OK';if(qualityValues[3])qualityValues[3].textContent=qualityData.records?fmt(Number(qualityData.records)):'—'}
}
