async function connectLive(){
  const cfg=window.LUMINA_CONFIG||{};
  if(!cfg.apiBaseUrl)return;
  const endpoints=['summary','stock-risk','forecast','kpis','inventory-plans','maintenance-risks','maintenance-analytics','operations','operations-analytics'];
  const payloadHasData=payload=>{
    const data=payload?.data;
    if(payload?.count>0)return true;
    if(Array.isArray(data))return data.length>0;
    if(data&&typeof data==='object'){
      const metrics=data.metrics||{};
      if(Object.values(metrics).some(value=>Number(value)>0))return true;
      if(['trend','concentration','streaming_insights','stockout_risks'].some(key=>Array.isArray(data[key])&&data[key].length>0))return true;
      if(Object.values(data).some(value=>Array.isArray(value)&&value.length>0))return true;
      if(Object.values(data).some(value=>typeof value==='number'&&value>0))return true;
    }
    return Boolean(payload?.counts&&Object.values(payload.counts).some(value=>Number(value)>0));
  };
  await Promise.all(endpoints.map(async endpoint=>{
    try{const scenarioQuery=endpoint==='kpis'?'':`&scenario_id=${encodeURIComponent(cfg.scenarioId||'')}`;const limit=endpoint==='stock-risk'?100:25;const response=await fetch(`${cfg.apiBaseUrl}/${endpoint}?limit=${limit}${scenarioQuery}`);if(!response.ok)throw new Error(`API ${response.status}`);state.live[endpoint]=await response.json();state.status[endpoint]=payloadHasData(state.live[endpoint])?'online':'amber'}catch(error){state.status[endpoint]=false;console.warn(`Ruta ${endpoint} no disponible`,error)}}));
  await Promise.all(Object.keys(state.master).map(async kind=>{
    try{const response=await fetch(`${cfg.apiBaseUrl}/catalog/${kind}?limit=100`);if(!response.ok)throw new Error(`API ${response.status}`);state.master[kind]=(await response.json()).data||[];state.status[`catalog/${kind}`]=state.master[kind].length?'online':'amber'}catch(error){state.status[`catalog/${kind}`]=false;console.warn(`Catálogo ${kind} no disponible`,error)}}));
  if(state.master.stores.length){const byId=new Map(state.master.stores.map(store=>[store.store_id,store]));riskStores.forEach(row=>{const store=byId.get(row[0]);if(store)row[1]=store.zone_name})}
  const kpiRows=state.live.kpis?.data||[];const currentKpi=kpiRows[0];if(currentKpi){network.orders=Number(currentKpi.orders||0);network.units=Number(currentKpi.units||0)}
  state.liveReady=Boolean(currentKpi);
  window.LUMINA_LIVE=Object.values(state.status).some(Boolean);
  render();
  hydrateLiveView();
  // Cada vista conserva sus propios indicadores y periodos.
}
connectLive();
const topActions=document.querySelector('.top-actions');if(topActions){const pollLabel=document.createElement('label');pollLabel.className='poll-control';pollLabel.innerHTML='<input id="gcp-polling" type="checkbox" checked><span>Actualizar automáticamente</span>';topActions.prepend(pollLabel);const polling=document.querySelector('#gcp-polling');let gcpPollTimer=setInterval(connectLive,10000);polling.addEventListener('change',()=>{if(gcpPollTimer)clearInterval(gcpPollTimer);if(polling.checked){connectLive();gcpPollTimer=setInterval(connectLive,10000)}});const userButton=document.querySelector('#user-button');if(userButton){userButton.querySelector('.avatar').textContent='↻';userButton.title='Actualizar datos en línea';userButton.addEventListener('click',()=>{state.updated='Actualizado ahora';connectLive()})}}
function operationsBarChart(rows){const data=(Array.isArray(rows)?rows:[]).filter(r=>r&&r.period_date&&Number(r.orders||0)>0).slice().reverse();if(!data.length)return '<div class="empty">Sin datos de volumen para el periodo seleccionado.</div>';const max=Math.max(...data.map(r=>Number(r.orders||0)),1);const previous=Number(data.at(-2)?.orders||0),current=Number(data.at(-1)?.orders||0),delta=previous?Math.round((current-previous)/previous*100):0;const reading=previous?(delta>=0?`El volumen creció ${Math.abs(delta)}% frente al periodo anterior.`:`El volumen disminuyó ${Math.abs(delta)}% frente al periodo anterior.`):'Se dispone del primer periodo de comparación.';const bars=data.map((r,i)=>`<div class="ops-bar-item ${i===data.length-1?'current':'previous'}"><div class="ops-bar-value">${fmt(Number(r.orders||0))}</div><div class="ops-bar-track"><i style="height:${Math.max(8,Number(r.orders||0)/max*100)}%"></i></div><span>${String(r.period_date).slice(5)}</span></div>`).join('');return `<div class="operations-bars"><div class="chart-legend"><span><i class="legend-dot previous-dot"></i>Periodo anterior</span><span><i class="legend-dot current-dot"></i>Periodo actual</span><strong>${delta>=0?'▲':'▼'} ${Math.abs(delta)}% vs. anterior</strong></div><div class="ops-bars-grid">${bars}</div><div class="chart-callout"><strong>Lectura de negocio:</strong> ${reading} Esta comparación ayuda a anticipar capacidad de preparación y entrega.</div></div>`}
function operationRowMarkup(r){const attention=Number(r.attention||0);const delivered=Number(r.delivered||0);const status=attention>0?'Requiere atención':delivered>0?'Entregado':'Procesado';const type=attention>0?'red':delivered>0?'':'amber';return `<tr><td><strong>Resumen diario · ${r.period_date||'Periodo actual'}</strong></td><td>Red operativa · 32 tiendas</td><td>${fmt(Number(r.units||r.quantity||0))}</td><td>${r.observed_at||r.period_date||'—'}</td><td>${badge(status,type)}</td></tr>`}
function maintenanceSeverityChart(rows){const data=(Array.isArray(rows)?rows:[]).slice().reverse();if(!data.length)return '<div class="empty">Sin tendencia de alertas disponible.</div>';const bars=data.map(r=>{const total=Math.max(1,Number(r.alerts||0)),high=Number(r.high_alerts||0),medium=Number(r.medium_alerts||0),normal=Math.max(0,total-high-medium);return `<div class="maint-bar-item"><strong>${fmt(total)} activos</strong><div class="maint-stack" title="${fmt(total)} activos con alerta"><i class="maint-high" style="height:${high/total*100}%"></i><i class="maint-medium" style="height:${medium/total*100}%"></i><i class="maint-normal" style="height:${normal/total*100}%"></i></div><span>${String(r.period_date).slice(5)}</span></div>`}).join('');return `<div class="maintenance-chart"><div class="chart-legend"><span><i class="legend-dot maint-high-dot"></i>Críticas</span><span><i class="legend-dot maint-medium-dot"></i>Preventivas</span><span><i class="legend-dot maint-normal-dot"></i>Seguimiento</span></div><div class="maint-bars">${bars}</div><div class="chart-callout"><strong>Lectura de negocio:</strong> cada barra representa activos únicos con alerta en el día; los segmentos muestran la proporción de severidad.</div></div>`}
